MAX_THRUST = 30.0  # Reduced significantly to prevent overheating
HEAT_SAFE_FRAC = 0.7  # More conservative heat management


def _waypoint(x, y):
    if x < G1_X - 0.1:
        return (G1_X, G1_Y)
    if x < G2_X - 0.1:
        return (G2_X, G2_Y)
    return (TARGET_X, TARGET_Y)


def build_agent(sandbox):
    # No physical agent to build - craft is already present
    return None


def agent_action(sandbox, agent_body, step_count):
    if sandbox.is_overheated():
        return
    pos = sandbox.get_craft_position()
    if pos is None:
        return
    x, y = pos
    heat = sandbox.get_heat()
    overheat_limit = sandbox.get_overheat_limit()
    remaining = overheat_limit - heat

    # Early exit if target is reached
    if TX_MIN <= x <= TX_MAX and TY_MIN <= y <= TY_MAX:
        sandbox.apply_thrust(0.0, 2.0)  # Minimal thrust to maintain position
        return

    # Reduce thrust when near heat limit
    if heat >= overheat_limit * HEAT_SAFE_FRAC:
        thrust_mag = min(MAX_THRUST * 0.3, remaining * 0.05)
    else:
        thrust_mag = min(MAX_THRUST, remaining * 0.15)

    # Determine target waypoint
    wx, wy = _waypoint(x, y)
    if x > 24.0:
        wy = 4.0
    if x < G1_X + 0.5 and y < 1.2:
        wy = max(wy, 1.3)
    if y < 1.4:
        wy = max(wy, 1.5)
    if G2_X - 1.0 <= x <= G2_X + 2.0 and y < 1.9:
        wy = max(wy, 2.2)
    if 20.5 <= x <= G2_X + 1.0 and y < 1.85:
        wx, wy = x + 0.3, 2.5

    # Calculate direction to waypoint
    dx = wx - x
    dy = wy - y
    dist = math.sqrt(dx * dx + dy * dy)
    if dist < 1e-6:
        sandbox.apply_thrust(0.0, 2.0)
        return

    ux = dx / dist
    uy = dy / dist

    # Apply thrust in direction of waypoint
    fx = thrust_mag * ux
    fy = thrust_mag * uy

    # Vertical adjustments to stay within gate bounds (reduced magnitude)
    if y < 1.4:
        fy += 10.0  # Reduced upward thrust
    if x < G1_X + 1.0 and y < 1.1:
        fy += min(10.0, (1.2 - y) * 15.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        fy += 30.0  # Reduced from 110.0

    # Cap total thrust to prevent excessive force
    total = math.sqrt(fx * fx + fy * fy)
    cap = thrust_mag * 1.5
    if y < 1.4:
        cap = max(cap, 60.0)
    if total > cap:
        scale = cap / total
        fx *= scale
        fy *= scale

    # Ensure forward movement by limiting backward thrust
    if fx < 0:
        fx = 0.0

    # Apply thrust
    sandbox.apply_thrust(fx, fy)

